280	/** duplicate_count → 각성 단계 계산 (모든 등급 최대 ★5) */
281	export function getAwakeningLevel(grade: string, duplicateCount: number): number {
282	  if (grade === 'R') {
283	    if (duplicateCount >= 100) return 5;
284	    if (duplicateCount >= 75)  return 4;
285	    if (duplicateCount >= 50)  return 3;
286	    if (duplicateCount >= 25)  return 2;
287	    if (duplicateCount >= 10)  return 1;
288	  } else if (grade === 'SR') {
289	    if (duplicateCount >= 40) return 5;
290	    if (duplicateCount >= 25) return 4;
291	    if (duplicateCount >= 15) return 3;
292	    if (duplicateCount >= 7)  return 2;
293	    if (duplicateCount >= 3)  return 1;
294	  } else if (grade === 'UR') {
295	    if (duplicateCount >= 10) return 5;
296	    if (duplicateCount >= 6)  return 4;
297	    if (duplicateCount >= 4)  return 3;
298	    if (duplicateCount >= 2)  return 2;
299	    if (duplicateCount >= 1)  return 1;
300	  }
301	  return 0;
302	}
303	
304	const DUPES_KEY     = 'duplicateCounts';
305	const DUPES_SIG_KEY = 'duplicateCountsSig';
306	const _DUPES_SALT   = 'ddong-dupes-\u0076\u0032';
307	
308	/** djb2 해시 — key:value 쌍을 정렬 후 직렬화해 서명 */
309	function _signDupes(map: Record<string, number>): string {
310	  const str = Object.entries(map)
311	    .sort(([a], [b]) => a.localeCompare(b))
312	    .map(([k, v]) => `${k}:${v}`)
313	    .join(',') + _DUPES_SALT;
314	  let h = 5381;
315	  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
316	  return h.toString(36);
317	}
318	
319	function _saveDupes(map: Record<string, number>): void {
320	  localStorage.setItem(DUPES_KEY, JSON.stringify(map));
321	  localStorage.setItem(DUPES_SIG_KEY, _signDupes(map));
322	}
323	
324	/** 캐릭터별 중복 획득 횟수 반환. 서명 불일치 시 변조로 판단해 전체 초기화. */
325	export function getDuplicateCount(id: string): number {
326	  try {
327	    const raw = localStorage.getItem(DUPES_KEY);
328	    const sig = localStorage.getItem(DUPES_SIG_KEY);
329	    const map: Record<string, number> = raw ? JSON.parse(raw) : {};
330	
331	    if (sig === null) {
332	      // 서명 미존재 → 기존 데이터 마이그레이션: 신뢰하고 서명 최초 발급
333	      _saveDupes(map);
334	      return map[id] ?? 0;
335	    }
336	
337	    // 서명 불일치 → 변조로 판단, 전체 초기화
338	    if (sig !== _signDupes(map)) {
339	      _saveDupes({});
340	      return 0;
341	    }
342	
343	    return map[id] ?? 0;
344	  } catch {
345	    return 0;
346	  }
347	}
348	
349	/** 캐릭터별 중복 획득 횟수 저장 (뽑기 완료 후 호출) */
350	export function setDuplicateCount(id: string, count: number): void {
351	  try {
352	    const raw = localStorage.getItem(DUPES_KEY);
353	    const sig = localStorage.getItem(DUPES_SIG_KEY);
354	    const map: Record<string, number> = raw ? JSON.parse(raw) : {};
355	
356	    // 변조된 상태에서 쓰기 시도 → 기존 맵 무시하고 새로 시작
357	    if (sig !== null && sig !== _signDupes(map)) {
358	      _saveDupes({ [id]: count });
359	      return;
360	    }
361	
362	    map[id] = count;
363	    _saveDupes(map);
364	  } catch { /* ignore */ }
365	}
366	
367	const OWNED_KEY = 'ownedCharacters';
368	const OWNED_SIG_KEY = 'ownedCharactersSig';
369	const SELECTED_KEY = 'selectedCharacter';
370	const _SIG_SALT = 'ddong-v2-\u0073\u006b\u006f\u0072';
371	
372	/** djb2 해시 → base36 문자열 (무결성 서명용) */
373	function _sign(list: string[]): string {
374	  const str = [...list].sort().join(',') + _SIG_SALT;
375	  let h = 5381;
376	  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
377	  return h.toString(36);
378	}
379	
380	/** 보유 목록과 서명을 함께 저장 (내부 전용) */
381	function _saveOwned(list: string[]): void {
382	  localStorage.setItem(OWNED_KEY, JSON.stringify(list));
383	  localStorage.setItem(OWNED_SIG_KEY, _sign(list));
384	}
385	
386	/** 보유 캐릭터 목록 반환. 서명 불일치 시 변조로 판단하여 초기화. */
387	export function getOwnedCharacters(): string[] {
388	  try {
389	    const raw = localStorage.getItem(OWNED_KEY);
390	    const sig = localStorage.getItem(OWNED_SIG_KEY);
391	    const list: string[] = raw ? JSON.parse(raw) : [];
392	    if (!list.includes('chibi')) list.unshift('chibi');
393	
394	    if (sig === null) {
395	      // 서명 미존재 → 기존 데이터 마이그레이션: 목록을 신뢰하고 서명 최초 발급
396	      _saveOwned(list);
397	      return list;
398	    }
399	
400	    // 서명 존재하지만 불일치 → 변조로 판단, chibi만 남김
401	    if (sig !== _sign(list)) {
402	      _saveOwned(['chibi']);
403	      return ['chibi'];
404	    }
405	
406	    return list;
407	  } catch {
408	    return ['chibi'];
409	  }
410	}
411	
412	/** 서버 동기화 등 외부에서 목록 전체를 덮어쓸 때 사용 (서명 함께 갱신) */
413	export function setOwnedCharacters(list: string[]): void {
414	  if (!list.includes('chibi')) list.unshift('chibi');
415	  _saveOwned(list);
416	}
417	
418	/** 캐릭터를 보유 목록에 추가 (뽑기 완료 후 호출) */
419	export function addOwnedCharacter(id: string): void {
420	  const owned = getOwnedCharacters();
421	  if (!owned.includes(id)) {
422	    owned.push(id);
423	    _saveOwned(owned);
424	  }
425	}
426	
427	/** 선택된 캐릭터 ID 반환. 없으면 'chibi'. */
428	export function getSelectedCharacter(): string {
429	  return localStorage.getItem(SELECTED_KEY) ?? 'chibi';
430	}
431	
432	/** 선택된 캐릭터 저장 */
433	export function setSelectedCharacter(id: string): void {
434	  localStorage.setItem(SELECTED_KEY, id);
435	}
436	
437	/** 소유 목록과 교차 검증하여 안전한 캐릭터 ID 반환. 미보유면 'chibi'로 강제 초기화. */
438	export function getSafeSelectedCharacter(): string {
439	  const selected = getSelectedCharacter();
440	  const owned = getOwnedCharacters();
441	  if (owned.includes(selected)) return selected;
442	  // 변조 감지 → chibi로 강제 초기화
443	  setSelectedCharacter('chibi');
444	  return 'chibi';
445	}
446	
447	/** 캐릭터 정의 조회 */
448	export function getCharacterDef(id: string): CharacterDef {
449	  return CHARACTERS.find(c => c.id === id) ?? CHARACTERS[0];
450	}
