21	  addAbilityBonus(amount: number): void;
22	  spawnGoldPoop(): void;
23	  spawnDiamondPoop(): void;
24	  spawnTopazPoop(): void;
25	  spawnRainbowPoop(): void;
26	  /** 특수 똥 수집 전체 처리 (카운트++, 점수, 획득 텍스트) */
27	  collectGoldPoop(poop: Phaser.Physics.Arcade.Sprite): void;
28	  collectDiamondPoop(poop: Phaser.Physics.Arcade.Sprite): void;
29	  collectTopazPoop(poop: Phaser.Physics.Arcade.Sprite): void;
30	  collectRainbowPoop(poop: Phaser.Physics.Arcade.Sprite): void;
31	}
32	
33	/** 특수 똥 타입 */
34	export type SpecialPoopType = 'gold' | 'diamond' | 'topaz' | 'rainbow';
