export class BaseAbility implements CharacterAbility {
  /** 0~3 각성 단계 (★0 기본 ~ ★3 풀 각성) */
  protected readonly awakeningLevel: number;

  constructor(awakeningLevel = 0) {
    this.awakeningLevel = awakeningLevel;
