import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { KNIGHT_PARAMS } from '../config/abilityParams';

/**
 * 나이트 (SR) — 이동속도 버프 / 점수마다 검기 발사
 * 수치: KNIGHT_PARAMS 참조
 */
export class KnightAbility extends BaseAbility {
  private lastBeamScore = 0;

  override getPlayerSpeedBonus(): number {
    return KNIGHT_PARAMS.speedBonus;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % KNIGHT_PARAMS.beamInterval === 0 && score > this.lastBeamScore) {
      this.lastBeamScore = score;
      this.fireBeam(api);
    }
  }

  private fireBeam(api: GameSceneAPI): void {
    const px = api.player.x;
    const py = api.player.y;
    const halfW = KNIGHT_PARAMS.beamHalfWidth;

    // 검기 경로 위 일반 똥 소멸 (플레이어보다 위쪽 + X 범위 내)
    const hit = api.poops
      .getChildren()
      .filter(p => {
        const sp = p as Phaser.Physics.Arcade.Sprite;
        return sp.active && sp.y < py && Math.abs(sp.x - px) <= halfW;
      }) as Phaser.Physics.Arcade.Sprite[];

    hit.forEach(poop => {
      this.spawnHitSpark(poop.x, poop.y, api);
      (poop as PoolablePoopBase).recycle();
    });

    this.drawBeamEffect(px, py, api);
  }

  /** 수직 빛줄기 이펙트 — 플레이어 위치에서 화면 상단까지 */
  private drawBeamEffect(px: number, py: number, api: GameSceneAPI): void {
    const scene = api.scene;
    const topY = 0;

    // 외곽 글로우 (넓고 투명)
    const glow = scene.add.graphics().setDepth(119);
    glow.fillStyle(0x88ccff, 0.25);
    glow.fillRect(px - 24, topY, 48, py - topY);

    // 중심 빛줄기 (좁고 밝음)
    const beam = scene.add.graphics().setDepth(120);
    beam.fillStyle(0xffffff, 0.85);
    beam.fillRect(px - 6, topY, 12, py - topY);

    // 칼날 끝부분 플래시
    const flash = scene.add.graphics().setDepth(121);
    flash.fillStyle(0xaaddff, 1);
    flash.fillTriangle(
      px - 14, py - 10,
      px + 14, py - 10,
      px, py - 50,
    );

    // 빔 페이드 아웃
    scene.tweens.add({
      targets: [glow, beam, flash],
      alpha: 0,
      duration: 350,
      ease: 'Cubic.easeOut',
      onComplete: () => { glow.destroy(); beam.destroy(); flash.destroy(); },
    });
  }

  /** 똥 소멸 위치에 검기 파편 스파크 */
  private spawnHitSpark(cx: number, cy: number, api: GameSceneAPI): void {
    const scene = api.scene;
    const SPARK_COUNT = 6;

    for (let i = 0; i < SPARK_COUNT; i++) {
      const spark = scene.add.graphics().setDepth(122);
      spark.fillStyle(0x88ccff, 1);
      const r = Phaser.Math.Between(2, 5);
      spark.fillCircle(0, 0, r);
      spark.setPosition(cx, cy);

      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const dist = Phaser.Math.Between(12, 30);
      scene.tweens.add({
        targets: spark,
        x: cx + Math.cos(angle) * dist,
        y: cy + Math.sin(angle) * dist - 10,
        alpha: 0,
        duration: Phaser.Math.Between(200, 400),
        ease: 'Quad.easeOut',
        onComplete: () => spark.destroy(),
      });
    }
  }
}

