      alpha: { from: 0.18, to: 0.50 },
      duration: 140,
      yoyo: true,
      repeat: -1,
      delay: 55,
      ease: 'Sine.easeInOut',
    });

    // ── 이동 & 충돌 감지 ─────────────────────────────────────────────
