      yoyo: true,
      repeat: -1,
      ease: 'Sine.easeInOut',
    });
    scene.tweens.add({
      targets: midGlow,
      scaleX: 1.12, scaleY: 1.12,
      alpha: { from: 0.18, to: 0.50 },
      duration: 140,
      yoyo: true,
      repeat: -1,
      delay: 55,
      ease: 'Sine.easeInOut',
    });

    // ── 이동 & 충돌 감지 ─────────────────────────────────────────────
    const hitSet    = new Set<Phaser.Physics.Arcade.Sprite>();
    const HIT_RADIUS = R_OUT + 10;

    scene.tweens.add({
      targets: all,
      x: `+=${dx * TRAVEL}`,
      y: `+=${dy * TRAVEL}`,
      duration,
      ease: 'Linear',
      onUpdate: () => {
        const cx = body.x;
        const cy = body.y;
        (api.poops.getChildren() as Phaser.Physics.Arcade.Sprite[]).forEach(sp => {
          if (!sp.active || hitSet.has(sp)) return;
          if (Phaser.Math.Distance.Between(cx, cy, sp.x, sp.y) <= HIT_RADIUS) {
            hitSet.add(sp);
            this.spawnHitSpark(sp.x, sp.y, api);
            (sp as PoolablePoopBase).recycle();
          }
        });
      },
