        scene.tweens.killTweensOf(all);
        all.forEach(g => g.destroy());
      },
    });
  }

  /** 검기에 닿은 똥 소멸 스파크 (연녹색) */
  private spawnHitSpark(cx: number, cy: number, api: GameSceneAPI): void {
