  /** 정적 초승달 꼭짓점 (로컬 좌표) */
  private buildCrescentPoints(): Phaser.Geom.Point[] {
    const tipY = (R_OUT * R_OUT - R_IN * R_IN + OFFSET * OFFSET) / (2 * OFFSET);
    const tipX = Math.sqrt(Math.max(0, R_OUT * R_OUT - tipY * tipY));
    const outerStart = Math.atan2(tipY, tipX);
    const outerSpan  = -(2 * Math.PI - (Math.atan2(tipY, -tipX) - outerStart));
    const innerStart = Math.atan2(tipY - OFFSET, -tipX);
    const innerSpan  = 2 * Math.PI - (innerStart - Math.atan2(tipY - OFFSET, tipX));
    const pts: Phaser.Geom.Point[] = [];
    for (let i = 0; i <= STEPS; i++) {
      const a = outerStart + outerSpan * (i / STEPS);
      pts.push(new Phaser.Geom.Point(Math.cos(a) * R_OUT, Math.sin(a) * R_OUT));
    }
    for (let i = 0; i <= STEPS; i++) {
      const a = innerStart + innerSpan * (i / STEPS);
      pts.push(new Phaser.Geom.Point(Math.cos(a) * R_IN, Math.sin(a) * R_IN + OFFSET));
    }
    return pts;
  }

  /**
   * sin파로 꼭짓점을 반지름 방향으로 흔든 꼭짓점 반환
   * @param time  scene.time.now
   * @param scale 기본 스케일 배율
   * @param speed 파형 속도
   * @param amp   진폭 (px)
   * @param phase 위상 오프셋
   */
  private wavyPoints(
    base: Phaser.Geom.Point[],
    time: number,
    scale = 1,
    speed = 0.008,
    amp = 3.5,
    phase = 0,
  ): Phaser.Geom.Point[] {
    return base.map((p, i) => {
      const r = Math.hypot(p.x, p.y);
      const wave = Math.sin(time * speed + i * 0.32 + phase) * amp;
      const s = r > 0.1 ? (r * scale + wave) / r : scale;
      return new Phaser.Geom.Point(p.x * s, p.y * s);
    });
  }

  private fireSingleCrescent(api: GameSceneAPI, rotationDeg: number): void {
    const scene  = api.scene;
    const px     = api.player.x;
    const py     = api.player.y - 20;
    const rotRad = rotationDeg * (Math.PI / 180);
    const dx     = Math.sin(rotRad);
    const dy     = -Math.cos(rotRad);

    const TRAVEL       = py + 80;
    const TRAVEL_SPEED = 520;
    const duration     = (TRAVEL / TRAVEL_SPEED) * 1000;

    const base = this.buildCrescentPoints();

    const makeGfx = (depth: number): Phaser.GameObjects.Graphics =>
      scene.add.graphics().setDepth(depth).setPosition(px, py).setRotation(rotRad);

    const outerGlow = makeGfx(118);
    const midGlow   = makeGfx(119);
    const body      = makeGfx(120);
    const edge      = makeGfx(121);
    const all       = [outerGlow, midGlow, body, edge];

    // ── 가장자리 파티클 방출 타이머 ────────────────────────────────
    const particleTimer = scene.time.addEvent({
      delay: 45,
      loop: true,
      callback: () => {
        if (!body.active) return;
        // base 꼭짓점 중 랜덤 하나 선택 → 월드 좌표로 변환
        const idx = Phaser.Math.Between(0, base.length - 1);
        const bp  = base[idx];
        // 회전 변환 적용
        const wx = body.x + bp.x * Math.cos(rotRad) - bp.y * Math.sin(rotRad);
        const wy = body.y + bp.x * Math.sin(rotRad) + bp.y * Math.cos(rotRad);
        this.emitEdgeSpark(wx, wy, scene);
      },
    });

    // ── 이동 & 매 프레임 재드로우 & 충돌 ──────────────────────────
    const hitSet     = new Set<Phaser.Physics.Arcade.Sprite>();
    const HIT_RADIUS = R_OUT + 10;

    scene.tweens.add({
      targets: all,
      x: `+=${dx * TRAVEL}`,
      y: `+=${dy * TRAVEL}`,
      duration,
      ease: 'Linear',
      onUpdate: () => {
        const t = scene.time.now;

        // 외부 글로우: 느리고 크게 일렁
        outerGlow.clear();
        outerGlow.fillStyle(0xff6600, 0.12 + Math.sin(t * 0.011) * 0.07);
        outerGlow.fillPoints(this.wavyPoints(base, t, 1.65, 0.007, 5.5, 0), true);

        // 중간 글로우: 중간 속도
        midGlow.clear();
        midGlow.fillStyle(0xff8800, 0.28 + Math.sin(t * 0.014 + 1.2) * 0.1);
        midGlow.fillPoints(this.wavyPoints(base, t, 1.25, 0.01, 3.5, 1.0), true);

        // 본체: 가장 빠른 잔물결
        body.clear();
        body.fillStyle(0xffaa44, 0.92);
        body.fillPoints(this.wavyPoints(base, t, 1.0, 0.013, 2.5, 2.1), true);

        // 외곽선: 본체와 같은 위상
        edge.clear();
        edge.lineStyle(2, 0xffeecc, 0.9);
        edge.strokePoints(this.wavyPoints(base, t, 1.0, 0.013, 2.5, 2.1), true);

        // 충돌 감지
        const cx = body.x;
        const cy = body.y;
        (api.poops.getChildren() as Phaser.Physics.Arcade.Sprite[]).forEach(sp => {
          if (!sp.active || hitSet.has(sp)) return;
          if (Phaser.Math.Distance.Between(cx, cy, sp.x, sp.y) <= HIT_RADIUS) {
            hitSet.add(sp);
            this.spawnHitSpark(sp.x, sp.y, api);
            (sp as PoolablePoopBase).recycle();
            api.addAbilityBonus(KNIGHT_PARAMS.beamKillBonus);
          }
        });
      },
      onComplete: () => {
        particleTimer.destroy();
        all.forEach(g => g.destroy());
      },
    });
  }

  /** 가장자리에서 흘러나오는 작은 불씨 */
  private emitEdgeSpark(wx: number, wy: number, scene: Phaser.Scene): void {
    const spark = scene.add.graphics().setDepth(122).setPosition(wx, wy);
    spark.fillStyle(Phaser.Math.Between(0, 1) ? 0xff9900 : 0xffcc44, 1);
    spark.fillCircle(0, 0, Phaser.Math.FloatBetween(1, 3));
    scene.tweens.add({
      targets: spark,
      x: wx + Phaser.Math.FloatBetween(-12, 12),
      y: wy + Phaser.Math.FloatBetween(-18, 4),
      alpha: 0,
      scaleX: 0.2,
      scaleY: 0.2,
      duration: Phaser.Math.Between(180, 320),
      ease: 'Quad.easeOut',
      onComplete: () => spark.destroy(),
    });
  }

  /** 검기에 닿은 똥 소멸 스파크 */
  private spawnHitSpark(cx: number, cy: number, api: GameSceneAPI): void {
    const scene = api.scene;
    for (let i = 0; i < 7; i++) {
      const spark = scene.add.graphics().setDepth(122).setPosition(cx, cy);
      spark.fillStyle(0xffaa55, 1);
      spark.fillCircle(0, 0, Phaser.Math.Between(2, 5));
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const dist  = Phaser.Math.Between(10, 28);
      scene.tweens.add({
        targets: spark,
        x: cx + Math.cos(angle) * dist,
        y: cy + Math.sin(angle) * dist - 8,
        alpha: 0,
        duration: Phaser.Math.Between(180, 380),
        ease: 'Quad.easeOut',
        onComplete: () => spark.destroy(),
      });
    }
  }
}

